import React, { useMemo } from 'react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { Image } from "@arco-design/web-react";
import ImageView from './ImageView';
import './style.less';
import Hljs from '@/components/custom/Hljs';

const ViewMarkdown = (props: any) => {

    const components = useMemo(() => {
        return {
            img: (props) => {
                return <ImageView key={props.src} {...props} />;
            },
            code: ({node, inline, className, children, ...props}) => {
                const match = /language-(\w+)/.exec(className || '');
                return !inline && match ? (
                    <Hljs code={match[1] as any}>{String(children).replace(/\n$/, '')}</Hljs>
                ) : (
                    <code className={className} {...props}>
                        {children}
                    </code>
                );
            }
        }
    },[])
    
    return (
        <Image.PreviewGroup>
            <ReactMarkdown
                className='custom-markdown-style'
                remarkPlugins={[remarkGfm]}
                {...props}
                components={components}
            />
        </Image.PreviewGroup>
    )
}

export default ViewMarkdown;